/* @lc app=leetcode id=2213 lang=kotlin */


class Solution { fun longestRepeating(s: String, queryCharacters: String, queryIndices: IntArray): IntArray = s.length.let { n -> Array<Any?>(8).apply { this[0] = IntArray(4 * n) }.apply { this[1] = IntArray(4 * n) }.apply { this[2] = IntArray(4 * n) }.apply { this[3] = CharArray(4 * n) }.apply { this[4] = CharArray(4 * n) }.apply { this[7] = { v: Int, tl: Int, tr: Int, tm: Int -> (this[0] as IntArray).let { tmX -> (this[1] as IntArray).let { tlX -> (this[2] as IntArray).let { trX -> (this[3] as CharArray).let { clX -> (this[4] as CharArray).let { crX -> clX.apply { this[v] = this[2 * v] }.let { crX.apply { this[v] = this[2 * v + 1] } }.let { tlX.apply { this[v] = this[2 * v] + if (this[2 * v] == (tm - tl + 1) && clX[2 * v] == clX[2 * v + 1]) this[2 * v + 1] else 0 } }.let { trX.apply { this[v] = this[2 * v + 1] + if (this[2 * v + 1] == (tr - tm) && crX[2 * v + 1] == crX[2 * v]) this[2 * v] else 0 } }.let { tmX.apply { this[v] = maxOf(maxOf(this[2 * v], this[2 * v + 1]), if (crX[2 * v] == clX[2 * v + 1]) trX[2 * v] + tlX[2 * v + 1] else 0) } } } } } } } } }.apply { this[5] = kotlin.DeepRecursiveFunction<IntArray, Unit> { args -> args[0].let { v -> args[1].let { tl -> args[2].let { tr -> if (tl == tr) (this@apply[0] as IntArray).let { it[v] = 1 }.also { (this@apply[1] as IntArray)[v] = 1 }.also { (this@apply[2] as IntArray)[v] = 1 }.also { (this@apply[3] as CharArray)[v] = s[tl] }.also { (this@apply[4] as CharArray)[v] = s[tl] } else ((tl + tr) / 2).let { tm -> callRecursive(intArrayOf(2 * v, tl, tm)).also { callRecursive(intArrayOf(2 * v + 1, tm + 1, tr)) }.also { (this@apply[7] as (Int, Int, Int, Int) -> Any)(v, tl, tr, tm) } } } } } }.apply { this[6] = kotlin.DeepRecursiveFunction<Triple<IntArray, Int, Char>, Unit> { params -> params.first[0].let { v -> params.first[1].let { tl -> params.first[2].let { tr -> if (tl == tr) (this@apply[3] as CharArray).let { it[v] = params.third }.also { (this@apply[4] as CharArray)[v] = params.third } else ((tl + tr) / 2).let { tm -> (if (params.second <= tm) callRecursive(params.copy(first = intArrayOf(2 * v, tl, tm))) else callRecursive(params.copy(first = intArrayOf(2 * v + 1, tm + 1, tr)))).also { (this@apply[7] as (Int, Int, Int, Int) -> Any)(v, tl, tr, tm) } } } } } } }.let { env -> (env[5] as kotlin.DeepRecursiveFunction<IntArray, Unit>).invoke(intArrayOf(1, 0, n - 1)).let { IntArray(queryIndices.size) { i -> (env[6] as kotlin.DeepRecursiveFunction<Triple<IntArray, Int, Char>, Unit>).invoke(Triple(intArrayOf(1, 0, n - 1), queryIndices[i], queryCharacters[i])).let { (env[0] as IntArray)[1] } } } } } }